"""Generate the display-only catalog. Run after editing catalog.json."""
import json
from pathlib import Path

ROOT = Path(__file__).resolve().parents[2]
catalog = json.loads(Path(__file__).with_name('catalog.json').read_text(encoding='utf-8'))
assert all(len(v) == 3 and all(isinstance(s, str) and s for s in v) for v in catalog.values())
rows = ',\n'.join('        {' + ','.join(json.dumps(s, ensure_ascii=False) for s in [k, *v]) + '}' for k, v in catalog.items())
source = '''package trade.gozero.bnt;

import java.util.*;
import java.util.regex.*;

/** Generated by tools/localization/generate.py. Presentation only: never pass
 * translated strings back into parsing, mining state or user configuration.
 * Single-pass, longest-phrase matching prevents recursive Japanese translation.
 * Native English diagnostics, identifiers and numeric data remain untouched. */
final class Translations {
    static final String[][] ROWS={
ROWS
    };
    private static final Map<String,String[]> TABLE=new HashMap<>();
    private static final Pattern PHRASES;
    private static final Pattern HAN=Pattern.compile("[\\\\p{IsHan}]");
    static {
        List<String> keys=new ArrayList<>();
        for(String[] row:ROWS){TABLE.put(row[0],row);keys.add(row[0]);}
        keys.sort((a,b)->Integer.compare(b.length(),a.length()));
        StringJoiner pattern=new StringJoiner("|");
        for(String key:keys)pattern.add(Pattern.quote(key));
        PHRASES=Pattern.compile(pattern.toString());
    }
    static String normalize(String language){
        return "en".equals(language)||"ru".equals(language)||"ja".equals(language)?language:"zh";
    }
    static String text(String source,String language){
        if(source==null)return "";
        int column="en".equals(language)?1:"ru".equals(language)?2:"ja".equals(language)?3:0;
        if(column==0)return source;
        String[] exact=TABLE.get(source);if(exact!=null)return exact[column];
        if(!HAN.matcher(source).find())return source;
        Matcher m=PHRASES.matcher(source);StringBuffer out=new StringBuffer();
        while(m.find())m.appendReplacement(out,Matcher.quoteReplacement(TABLE.get(m.group())[column]));
        m.appendTail(out);return out.toString();
    }
    private Translations(){}
}
'''.replace('\nROWS\n', '\n' + rows + '\n')
(ROOT/'app/src/main/java/trade/gozero/bnt/Translations.java').write_text(source, encoding='utf-8', newline='\n')
print(f'Generated {len(catalog)} phrases in four languages')
